interface HomePost {
  fields: {
    slug: string;
    preview: string;
  };
  frontmatter: {
    title: string;
    date: string;
    category: string;
    tags: string[];
    description: string;
  };
  excerpt: string;
  timeToRead: number;
}

interface FeaturedImage {
  relativePath: string;
  publicURL: string | null;
}

interface Props {
  data: {
    allMarkdownRemark: {
      totalCount: number;
      nodes: HomePost[];
    };
    featuredImages: {
      nodes: FeaturedImage[];
    };
  };
  location: { search: string };
}

const POSTS_PER_BATCH = 6;
const DEFAULT_VISIBLE_TAGS = 10;

const postMatchesQuery = (post: HomePost, query: string) => {
  if (!query) return true;
  const searchableText = [
    post.frontmatter.title,
    post.frontmatter.description,
    post.frontmatter.category,
    ...post.frontmatter.tags,
  ]
    .join(' ')
    .toLocaleLowerCase('ko');
  return searchableText.includes(query.toLocaleLowerCase('ko'));
};

const scoreTags = (posts: HomePost[]) => {
  const newestDate = Math.max(...posts.map((post) => Date.parse(post.frontmatter.date)));
  const scores = new Map<string, { count: number; score: number }>();

  for (const post of posts) {
    const ageInDays = Math.max(0, (newestDate - Date.parse(post.frontmatter.date)) / 86_400_000);
    const recencyScore = Math.exp(-ageInDays / 365);
    for (const tag of post.frontmatter.tags) {
      const current = scores.get(tag) || { count: 0, score: 0 };
      current.count += 1;
      const isFeatured = config.featuredTags.some((featuredTag) => featuredTag === tag);
      current.score += recencyScore + (isFeatured ? 2 : 0);
      scores.set(tag, current);
    }
  }

  return [...scores.entries()].sort((left, right) => {
    if (right[1].score !== left[1].score) return right[1].score - left[1].score;
    return left[0].localeCompare(right[0], 'ko');
  });
};

const FeaturedCarousel = ({ posts, images }: { posts: HomePost[]; images: FeaturedImage[] }) => {
  const viewportRef = useRef<HTMLDivElement>(null);
  const postsBySlug = new Map(posts.map((post) => [post.fields.slug, post]));
  const imagesByPath = new Map<string, string>();

  for (const image of images) {
    if (image.publicURL) imagesByPath.set(image.relativePath, image.publicURL);
  }

  const featuredPosts = config.featuredPosts.flatMap((featuredPost) => {
    const post = postsBySlug.get(featuredPost.slug);
    if (!post) return [];

    return [
      {
        post,
        image: featuredPost.image
          ? imagesByPath.get(featuredPost.image) || config.defaultBg
          : config.defaultBg,
      },
    ];
  });

  const scroll = (direction: -1 | 1) => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    viewport.scrollBy({
      left: direction * Math.max(320, viewport.clientWidth * 0.82),
      behavior: 'smooth',
    });
  };

  if (!featuredPosts.length) return null;

  return (
    <FeaturedSection aria-labelledby="featured-posts-title">
      <FeaturedHeader>
        <div>
          <FeaturedEyebrow>Editor&apos;s pick</FeaturedEyebrow>
          <h2 id="featured-posts-title">추천 글</h2>
        </div>
        <SliderControls aria-label="추천 글 이동">
          <button type="button" onClick={() => scroll(-1)} aria-label="이전 추천 글">
            ←
          </button>
          <button type="button" onClick={() => scroll(1)} aria-label="다음 추천 글">
            →
          </button>
        </SliderControls>
      </FeaturedHeader>
      <FeaturedViewport ref={viewportRef} tabIndex={0}>
        {featuredPosts.map(({ post, image }, index) => (
          <FeaturedCard to={`/blog/${post.fields.slug}/`} key={post.fields.slug}>
            <FeaturedImage>
              <img
                src={image}
                alt=""
                loading={index < 2 ? 'eager' : 'lazy'}
                width="640"
                height="360"
              />
            </FeaturedImage>
            <FeaturedBody>
              <FeaturedMeta>
                <span>{post.frontmatter.category}</span>
                <span>{post.timeToRead}분</span>
              </FeaturedMeta>
              <h3>{post.frontmatter.title}</h3>
              <p>{post.fields.preview}</p>
            </FeaturedBody>
          </FeaturedCard>
        ))}
      </FeaturedViewport>
    </FeaturedSection>
  );
};

const PostResults = ({ posts }: { posts: HomePost[] }) => {
  const [visibleCount, setVisibleCount] = useState(POSTS_PER_BATCH);
  const loadMoreRef = useRef<HTMLDivElement>(null);
  const visiblePosts = posts.slice(0, visibleCount);
  const hasMore = visibleCount < posts.length;

  useEffect(() => {
    const sentinel = loadMoreRef.current;
    if (!sentinel || !hasMore) return undefined;

    if (!('IntersectionObserver' in window)) {
      const timeout = setTimeout(() => setVisibleCount(posts.length), 0);
      return () => clearTimeout(timeout);
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry.isIntersecting) return;
        setVisibleCount((count) => Math.min(count + POSTS_PER_BATCH, posts.length));
      },
      { rootMargin: '320px 0px' },
    );

    observer.observe(sentinel);
    return () => observer.disconnect();
  }, [hasMore, posts.length]);

  if (!posts.length) {
    return (
      <EmptyState>
        <h2>조건에 맞는 글이 없습니다.</h2>
        <p>검색어나 필터를 바꾸거나 전체 글로 돌아가 보세요.</p>
        <Link to="/">필터 초기화</Link>
      </EmptyState>
    );
  }

  return (
    <>
      {visiblePosts.map((post) => (
        <Article
          title={post.frontmatter.title}
          date={post.frontmatter.date}
          excerpt={post.fields.preview || post.frontmatter.description || post.excerpt}
          timeToRead={post.timeToRead}
          slug={post.fields.slug}
          category={post.frontmatter.category}
          key={post.fields.slug}
        />
      ))}
      {hasMore ? (
        <LoadingSentinel ref={loadMoreRef} role="status" aria-live="polite">
          다음 글을 불러오는 중…
        </LoadingSentinel>
      ) : null}
    </>
  );
};

interface FilterPanelProps {
  children: React.ReactNode;
  className: string;
  summary: string;
  title: string;
}

const FilterPanel = ({ children, className, summary, title }: FilterPanelProps) => {
  const panelRef = useRef<HTMLDetailsElement>(null);

  useEffect(() => {
    const panel = panelRef.current;
    if (!panel) return undefined;

    const tabletQuery = window.matchMedia('(max-width: 1200px)');
    const syncPanel = () => {
      panel.open = !tabletQuery.matches;
    };
    syncPanel();
    tabletQuery.addEventListener('change', syncPanel);
    return () => tabletQuery.removeEventListener('change', syncPanel);
  }, []);

  return (
    <SidePanel ref={panelRef} className={className} open>
      <summary>
        <strong>{title}</strong>
        <span>{summary}</span>
      </summary>
      <h2>{title}</h2>
      {children}
    </SidePanel>
  );
};

export default function IndexPage({ data, location }: Props) {
  const { nodes: posts, totalCount } = data.allMarkdownRemark;
  const searchParams = new URLSearchParams(location.search);
  const requestedCategory = searchParams.get('category') || 'all';
  const category = config.categories.some(
    (configuredCategory) => configuredCategory === requestedCategory,
  )
    ? requestedCategory
    : 'all';
  const tag = searchParams.get('tag') || 'all';
  const query = searchParams.get('q')?.trim() || '';
  const tagScores = useMemo(() => scoreTags(posts), [posts]);
  const [showAllTags, setShowAllTags] = useState(false);
  const activeHiddenTag =
    !showAllTags && tag !== 'all'
      ? tagScores.slice(DEFAULT_VISIBLE_TAGS).find(([tagName]) => tagName === tag)
      : undefined;
  const visibleTagScores = showAllTags
    ? tagScores
    : [...tagScores.slice(0, DEFAULT_VISIBLE_TAGS), ...(activeHiddenTag ? [activeHiddenTag] : [])];
  const hiddenTagCount = Math.max(0, tagScores.length - DEFAULT_VISIBLE_TAGS);
  const remainingHiddenTagCount = tagScores.length - visibleTagScores.length;

  const categoryCounts = new Map<string, number>();
  for (const post of posts) {
    categoryCounts.set(
      post.frontmatter.category,
      (categoryCounts.get(post.frontmatter.category) || 0) + 1,
    );
  }

  const filteredPosts = posts.filter((post) => {
    const categoryMatches = category === 'all' || post.frontmatter.category === category;
    const tagMatches = tag === 'all' || post.frontmatter.tags.includes(tag);
    return categoryMatches && tagMatches && postMatchesQuery(post, query);
  });

  const filterHref = (nextCategory: string, nextTag: string) => {
    const params = new URLSearchParams();
    if (nextCategory !== 'all') params.set('category', nextCategory);
    if (nextTag !== 'all') params.set('tag', nextTag);
    if (query) params.set('q', query);
    const search = params.toString();
    return search ? `/?${search}` : '/';
  };

  const handleSearch = (event: React.ChangeEvent<HTMLInputElement>) => {
    const params = new URLSearchParams(location.search);
    const value = event.target.value;
    if (value) params.set('q', value);
    else params.delete('q');
    const search = params.toString();
    void navigate(search ? `/?${search}` : '/', { replace: true });
  };

  return (
    <Layout>
      <Hero>
        <HeroInner>
          <img src={config.siteLogo} alt="" width="72" height="72" />
          <p>모르면 공부하고, 공부했으면 정리합니다.</p>
          <h1>{config.siteTitle}</h1>
          <p>{config.siteDescription}</p>
          <HeroNavigation aria-label="주요 메뉴">
            <HeroLink to="/blog/">전체 글 {totalCount}</HeroLink>
          </HeroNavigation>
        </HeroInner>
      </Hero>

      <FeaturedCarousel posts={posts} images={data.featuredImages.nodes} />

      <Explorer aria-label="글 탐색">
        <FilterRail>
          <FilterPanel
            className="categories"
            title="카테고리"
            summary={category === 'all' ? '전체' : category}
          >
            <FilterList>
              {config.categories.map((item) => (
                <li key={item}>
                  <FilterLink
                    to={filterHref(item, tag)}
                    $active={category === item}
                    aria-current={category === item ? 'page' : undefined}
                  >
                    <span>{item === 'all' ? '전체' : item}</span>
                    <small>{item === 'all' ? totalCount : categoryCounts.get(item) || 0}</small>
                  </FilterLink>
                </li>
              ))}
            </FilterList>
          </FilterPanel>

          <FilterPanel className="tags" title="태그" summary={tag === 'all' ? '전체 태그' : tag}>
            <FilterList>
              <li>
                <FilterLink
                  to={filterHref(category, 'all')}
                  $active={tag === 'all'}
                  aria-current={tag === 'all' ? 'page' : undefined}
                >
                  <span>전체 태그</span>
                  <small>{tagScores.length}</small>
                </FilterLink>
              </li>
              {visibleTagScores.map(([item, stats]) => (
                <li key={item}>
                  <FilterLink
                    to={filterHref(category, tag === item ? 'all' : item)}
                    $active={tag === item}
                    aria-current={tag === item ? 'page' : undefined}
                  >
                    <span>{item}</span>
                    <small>{stats.count}</small>
                  </FilterLink>
                </li>
              ))}
              {hiddenTagCount ? (
                <li>
                  <TagToggleButton
                    type="button"
                    aria-expanded={showAllTags}
                    onClick={() => setShowAllTags((isExpanded) => !isExpanded)}
                  >
                    {showAllTags ? '태그 접기' : `${remainingHiddenTagCount}개 태그 더보기`}
                    <span aria-hidden="true">{showAllTags ? '−' : '+'}</span>
                  </TagToggleButton>
                </li>
              ) : null}
            </FilterList>
          </FilterPanel>
        </FilterRail>

        <MainColumn>
          <SearchLabel htmlFor="post-search">글 검색</SearchLabel>
          <SearchInput
            id="post-search"
            type="search"
            value={query}
            onChange={handleSearch}
            placeholder="제목, 설명, 태그 검색"
          />
          <ResultHeader>
            <div>
              <h2>{category === 'all' ? '전체 글' : category}</h2>
              <p>
                {tag !== 'all' ? `${tag} · ` : ''}
                {query ? `“${query}” · ` : ''}
                {filteredPosts.length}개
              </p>
            </div>
            <p>
              {tag !== 'all' && TagDescription[tag]
                ? TagDescription[tag]
                : CategoryDescription[category]}
            </p>
          </ResultHeader>
          <PostResults key={`${category}:${tag}:${query}`} posts={filteredPosts} />
        </MainColumn>
      </Explorer>
    </Layout>
  );
}

export const Head = () => <SEO pathname="/" />;

export const IndexQuery = graphql`
  query IndexPage {
    allMarkdownRemark(
      filter: { frontmatter: { draft: { ne: true } } }
      sort: { frontmatter: { date: DESC } }
    ) {
      totalCount
      nodes {
        id
        fields {
          slug
          preview
        }
        frontmatter {
          title
          date(formatString: "YYYY-MM-DD")
          category
          tags
          description
        }
        excerpt(pruneLength: 150)
        timeToRead
      }
    }
    featuredImages: allFile(filter: { extension: { in: ["png", "jpg", "jpeg", "webp"] } }) {
      nodes {
        relativePath
        publicURL
      }
    }
  }
`;

